# 24b_thin_refit.R  Are PSP thinning removals counted as deaths in the mortality frame of E6r, and what changes when the intervals that end in or span a
# removal year are censored (the rule of the earlier versions; removal years from psp_origin_thinning_2026-09-16_DATA.csv)? No identifier printed.
suppressMessages(library(data.table)); options(width=220); setwd("~/jobs/koa_final_eq_20261110"); FT <- readRDS("out/rdbyi_fits.rds"); bs <- FT$bs; bm <- FT$bm
th <- fread("~/jobs/koa_v105final_20261103/inputs/psp_origin_thinning_2026-09-16_DATA.csv"); rem <- th[removal_t1_years != "" & !is.na(removal_t1_years), .(yr = as.integer(unlist(strsplit(as.character(removal_t1_years), ";")))), by = .(Data, Install = as.character(Install))]
mf <- as.data.table(readRDS("frames/mf_confirmed.rds")); mf[, Install := as.character(Install)]; mf[, rid := .I]; x <- merge(mf[, .(rid, Data, Install, Measure, e_Measure)], rem, by = c("Data", "Install"), allow.cartesian = TRUE)[yr > Measure & yr <= e_Measure]; mf[, thin := rid %in% x$rid]
cat("mortality frame: rows", nrow(mf), " deaths", sum(mf$died), "\nby origin and PSP source:\n"); print(mf[, .(rows = .N, deaths = sum(died), rows_removal_interval = sum(thin), deaths_removal_interval = sum(died & thin), annual_rate_removal = round(sum(died[thin]) / sum(yip[thin]), 4), annual_rate_other = round(sum(died[!thin]) / sum(yip[!thin]), 4)), by = .(planted, psp = Data == "PSP")])
pi <- mf[, .(n = .N, d = sum(died), yip = yip[1]), by = .(pid, Measure, thin, Data)][, frac := d / n]; cat("plot-interval death fraction, PSP: removal intervals quantiles (10, 50, 90%)", round(quantile(pi[Data == "PSP" & thin == TRUE, frac], c(.1, .5, .9)), 3), " n", nrow(pi[Data == "PSP" & thin == TRUE]), "; other PSP intervals", round(quantile(pi[Data == "PSP" & thin == FALSE, frac], c(.1, .5, .9)), 3), " n", nrow(pi[Data == "PSP" & thin == FALSE]), "\n")
mf[, `:=`(ld = log(dbh_m + 1), lbyi = log(BYI), sm = exp(bs[[1]] + bs[[2]] * log(BYI) + bs[[3]] * planted))]; mf[, lrd := log(pmax(SDI_koa / sm, 0.001))]
fit <- function(d) { X <- cbind(1, d$ld, d$dbh_m, d$dbh_m^2, d$BAL, d$lrd, d$lbyi, d$planted); mu <- c(0, colMeans(X[, -1])); sdv <- c(1, apply(X[, -1], 2, sd)); Z <- sweep(sweep(X, 2, mu), 2, sdv, "/"); Z[, 1] <- 1; y <- d$died; o <- log(d$yip)
  nll <- function(z) { h <- exp(pmin(as.numeric(Z %*% z) + o, 30)); -sum(ifelse(y == 1, log(-expm1(-h)), -h)) }; gr <- function(z) { h <- exp(pmin(as.numeric(Z %*% z) + o, 30)); -as.numeric(crossprod(Z, ifelse(y == 1, h * exp(-h) / (-expm1(-h)), -h))) }
  z0 <- bm * sdv; z0[1] <- bm[1] + sum(bm[-1] * mu[-1]); op <- nlminb(z0, nll, gr, control = list(iter.max = 1000, eval.max = 2000, rel.tol = 1e-12)); b <- op$par / sdv; b[1] <- op$par[1] - sum(b[-1] * mu[-1]); list(b = setNames(b, names(bm)), gmax = max(abs(gr(op$par)))) }
A <- fit(mf); C <- fit(mf[thin == FALSE]); cat("\nE6r, all rows (must reproduce script 22; largest difference", signif(max(abs(A$b - bm)), 3), ") and with removal intervals censored (rows", nrow(mf[thin == FALSE]), ", deaths", sum(mf[thin == FALSE, died]), "; gradient", signif(C$gmax, 3), ")\n"); print(round(rbind(all = A$b, censored = C$b), 5))
pr <- function(b, dbh, rd, byi, pl, bal = 10) 1 - exp(-exp(b[[1]] + b[[2]] * log(dbh + 1) + b[[3]] * dbh + b[[4]] * dbh^2 + b[[5]] * bal + b[[6]] * log(rd) + b[[7]] * log(byi) + b[[8]] * pl))
g <- CJ(planted = c(0, 1), dbh = c(5, 15, 30, 60), rd = c(0.3, 0.6, 1.0)); g[, byi := ifelse(planted == 1, 156, 248)]; g[, `:=`(p_all = round(pr(A$b, dbh, rd, byi, planted), 4), p_censored = round(pr(C$b, dbh, rd, byi, planted), 4))]; g[, ratio := round(p_censored / p_all, 2)]; cat("annual mortality probability, BAL 10:\n"); print(g)
cat("diameter of lowest mortality (cm): all", round(uniroot(function(x) A$b[[2]] / (x + 1) + A$b[[3]] + 2 * A$b[[4]] * x, c(5, 400))$root, 1), "; censored", tryCatch(round(uniroot(function(x) C$b[[2]] / (x + 1) + C$b[[3]] + 2 * C$b[[4]] * x, c(5, 400))$root, 1), error = function(e) "none in 5 to 400"), "\n")
d <- as.data.table(f <- readRDS("frames/frames.rds")$df)[keep_fixed == TRUE]; d[, Install := as.character(Install)]; d[, rid := .I]; y <- merge(d[, .(rid, Data, Install, Measure, e_Measure)], rem, by = c("Data", "Install"), allow.cartesian = TRUE)[yr > Measure & yr <= e_Measure]
cat("diameter increment frame: rows", nrow(d), "; rows in removal intervals", uniqueN(y$rid), "(live trees only, so no removal is counted as growth; competition changes within the interval)\n")
saveRDS(list(thin_rid = mf[thin == TRUE, rid], b_cens = C$b), "out/thin_check.rds"); cat("24b done\n")
